const initialConfirmData = {
  confirmModalOpen: false,
  confirmMessage: '',
  confirmedBatch: {},
};

// The up/down arrows next to the batch name tell the user it can be switched (the select shows only the name otherwise).
const BatchArrows = props => <UnfoldMoreRounded {...props} fontSize="small" />;

function BatchSwitch({ hideClone }) {
  // const classes = useStyles();
  const history = useHistory();
  const dispatch = useDispatch();
  const globalSchool = getGlobalSchoolUtils();
  const { startYear: currentStartYear } = getCurrentYearBatchUtils();
  const { startYear, batchId } = getGlobalCurrentBatchUtils();
  const { batchId: actualCurrentBatchId, startYear: actualStartYear } =
    getGlobalCurrentBatchUtils('actualCurrentBatch');
  const reduxStore = useSelector(state => state);
  const {
    auth: { loggedUserToken, loggedUserSchool },
    batches: { batchList },
  } = reduxStore;
  const [batch, setBatch] = useState({});
  const [batchSwitchConfirmData, setConfirmData] = useState(initialConfirmData);
  // Students are promoted out of the running year or an earlier one (a school that missed it can still do it); a future batch has
  // nobody to move yet, so the button is not shown there.
  const canPromoteFrom = batch?.startYear <= (actualStartYear || currentStartYear);

  const updateBatch = () => {
    if (!batchList?.length) {
      if (globalSchool?.schoolId) {
        dispatch(
          fetchSchoolBatchsService({
            schoolId: globalSchool?.schoolId || loggedUserSchool,
            token: loggedUserToken,
          })
        );
      }
    } else {
      // The saved batch must be one of this school's batches. When it is missing (a fresh browser, or the saved choice is gone) or its id
      // is not this school's (a leftover from another server or school) every page asks for the classes of a batch that is not
      // there and shows an empty school. So the running year's batch (else the latest) is saved instead.
      const byId = batchList.findIndex(el => el?.batchId === batchId);
      const itemIndex = byId > -1 ? byId : batchList.findIndex(el => el?.startYear === startYear);
      if (byId === -1) {
        const pick =
          batchList[itemIndex] ||
          batchList.find(el => el?.startYear === currentStartYear) ||
          [...batchList].sort((a, b) => b.startYear - a.startYear)[0];
        if (pick) {
          const bData = { batchId: pick.batchId, startYear: pick.startYear, endYear: pick.endYear };
          setGlobalCurrentBatchUtils(bData);
          if (!actualCurrentBatchId || !batchList.some(el => el?.batchId === actualCurrentBatchId)) {
            setGlobalActualCurrentBatchUtils(bData);
          }
          setBatch({ ...pick, isActive: true, itemIndex: batchList.indexOf(pick) });
          // the page on screen has already asked for the old batch: load it again with the right one (once, the saved batch now matches)
          window.location.reload();
          return;
        }
      }
      if (!batch?.batchId && itemIndex !== null && itemIndex > -1) {
        const batchItem = batchList?.[itemIndex];
        setBatch({ ...batchItem, isActive: true, itemIndex });
      }
    }
  };

  useEffect(() => {
    updateBatch();
  }, [batchList?.length, globalSchool?.schoolId]);

  const confirmNo = () => {
    setConfirmData(initialConfirmData);
  };

  const confirmYes = () => {
    const bData = {
      batchId: batchSwitchConfirmData?.confirmedBatch?.batchId,
      startYear: batchSwitchConfirmData?.confirmedBatch?.startYear,
      endYear: batchSwitchConfirmData?.confirmedBatch?.endYear,
    };
    setGlobalCurrentBatchUtils(bData);
    setBatch(batchSwitchConfirmData?.confirmedBatch);
    confirmNo();
    dispatch({ type: 'CLEAR_STORE_EXCEPT_AUTH_SCHOOL' });
    history.push(`/admin/dashboard`);
  };

  const findAndUpdateStateBatch = passBatchId => {
    const batchItem = passBatchId && batchList?.find(el => el?.batchId === passBatchId);
    if (batchItem) {
      setConfirmData(prevState => ({
        ...prevState,
        confirmModalOpen: true,
        confirmMessage: `Changing batch will reset your app to batch ${batchItem?.startYear} - ${batchItem?.endYear}. Are you sure you want to proceed?`,
        confirmedBatch: batchItem,
      }));
    } else {
      confirmNo();
    }
  };

  const handleChange = event => {
    findAndUpdateStateBatch(event.target.value);
  };

  return batch?.batchId ? (
    <>
      <Row className="align-items-center">
        <Select
          labelId="demo-simple-select-label"
          id="demo-simple-select"
          value={batchList?.length ? batch?.batchId : ''}
          onChange={handleChange}
          IconComponent={BatchArrows}
          //className={classes.select}
        >
          {batchList?.map(el => {
            return (
              <MenuItem key={el?.batchId} value={el?.batchId}>
                <CommonTooltip
                  style={{ fontSize: 17 }}
                  placement="right"
                  content={el?.batchId === actualCurrentBatchId ? 'Current batch' : 'Exist batch'}>
                  {el?.batchId === actualCurrentBatchId ? (
                    <Brightness1Icon style={{ fontSize: 16, color: 'green', margin: '-3px 5px 0px 0px' }} />
                  ) : (
                    <Brightness1Icon style={{ fontSize: 16, color: 'orange', margin: '-3px 5px 0px 0px' }} />
                  )}
                  <span className="ml-1">{el?.name}</span>
                </CommonTooltip>
              </MenuItem>
            );
          })}
        </Select>
        {batchList?.length > 0 && canPromoteFrom && !hideClone && (
          <span style={{ marginLeft: 0 }}>
            <CommonTooltip
              content={`Student promotion: move the students of ${batch?.startYear} - ${batch?.endYear} up to the next class in the new year`}
              placement="bottom">
              {/* the old "clone batch" page is replaced by the Student promotion wizard (class order, new batch, review, promote) */}
              <Button
                className="batch-promote-btn"
                size="small"
                startIcon={<TrendingUpRounded fontSize="small" />}
                onClick={() => history.push(`/admin/student-promotion?step=0&batch=${encodeUrlId(batch?.batchId)}`)}>
                <span className="batch-promote-text">Promote students</span>
              </Button>
            </CommonTooltip>
          </span>
        )}
      </Row>
      <ConfirmModal
        headerStyle={{ fontSize: 18 }}
        size="md"
        confirmModalOpen={batchSwitchConfirmData?.confirmModalOpen}
        deleteConfirm={confirmYes}
        deleteCancel={confirmNo}
        confirmMessage={batchSwitchConfirmData?.confirmMessage}
      />
    </>
  ) : null;
}

export default BatchSwitch;
