import React, { useEffect, useMemo, useState } from 'react';
import { useSelector } from 'react-redux';
import Menu from '@material-ui/core/Menu';
import MenuItem from '@material-ui/core/MenuItem';
import CheckIcon from '@material-ui/icons/Check';
import UnfoldMoreRounded from '@material-ui/icons/UnfoldMoreRounded';
import { fetchAllSchoolsPlainApi } from 'actions/admin/schools';
import { getGlobalSchoolUtils } from 'utils/commonFunc';
import { switchSchool } from 'utils/schoolSwitch';
import { cacheGet, cacheSet } from 'utils/softCache';
import colors from 'config/colors';

// The school the whole app is working in, in the top bar (next to the batch), for the super admin, who works in every school. Picking
// another school reloads the app on that school: its dashboard, its batches, classes, staff - every page follows it.
const SchoolSwitch = () => {
  const token = useSelector(state => state.auth.loggedUserToken);
  const current = getGlobalSchoolUtils();
  const [schools, setSchools] = useState(cacheGet('schools:all') || []);
  const [anchor, setAnchor] = useState(null);
  const [text, setText] = useState('');

  useEffect(() => {
    if (!token) return undefined;
    let cancelled = false;
    fetchAllSchoolsPlainApi({ token })
      .then(list => {
        if (cancelled) return;
        setSchools(list);
        cacheSet('schools:all', list);
      })
      .catch(() => {});
    return () => {
      cancelled = true;
    };
  }, [token]);

  const shown = useMemo(() => {
    const needle = text.trim().toLowerCase();
    return schools
      .filter(school => !needle || `${school.schoolName} ${school.schoolCode}`.toLowerCase().includes(needle))
      .sort((a, b) => String(a.schoolName).localeCompare(String(b.schoolName)));
  }, [schools, text]);

  const close = () => {
    setAnchor(null);
    setText('');
  };

  return (
    <>
      <button
        type="button"
        className="school-switch-btn"
        aria-haspopup="true"
        title="Switch school"
        onClick={event => setAnchor(event.currentTarget)}
        style={{
          display: 'inline-flex',
          alignItems: 'center',
          gap: 8,
          maxWidth: 260,
          padding: '5px 12px',
          border: '1px solid #e8e3f0',
          borderRadius: 999,
          background: '#fff',
          color: colors.grey1,
          fontSize: 13,
          fontWeight: 700,
          cursor: 'pointer',
        }}>
        <i className="fas fa-school" aria-hidden="true" style={{ color: colors.accent }} />
        <span style={{ overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
          {current?.schoolName || 'Select school'}
        </span>
        <UnfoldMoreRounded fontSize="small" style={{ color: colors.grey3 }} />
      </button>
      <Menu
        anchorEl={anchor}
        open={!!anchor}
        onClose={close}
        getContentAnchorEl={null}
        anchorOrigin={{ vertical: 'bottom', horizontal: 'left' }}
        transformOrigin={{ vertical: 'top', horizontal: 'left' }}
        PaperProps={{ style: { maxHeight: 360, minWidth: 280, borderRadius: 12 } }}>
        {schools.length > 6 && (
          <div style={{ padding: '6px 12px 8px' }}>
            <input
              autoFocus
              className="form-control"
              style={{ height: 34, borderRadius: 12, fontSize: 13 }}
              placeholder="Search school"
              value={text}
              onChange={e => setText(e.target.value)}
              onKeyDown={e => e.stopPropagation()}
            />
          </div>
        )}
        {shown.map(school => {
          const isCurrent = school.schoolId === current?.schoolId;
          return (
            <MenuItem
              key={school.schoolId}
              selected={isCurrent}
              onClick={() => {
                close();
                if (!isCurrent) switchSchool(school);
              }}
              style={{ gap: 10 }}>
              <span style={{ flex: 1, minWidth: 0 }}>
                <span style={{ display: 'block', fontWeight: isCurrent ? 700 : 500 }}>{school.schoolName}</span>
                <small style={{ color: colors.grey3 }}>{school.schoolCode}</small>
              </span>
              {isCurrent && <CheckIcon fontSize="small" style={{ color: colors.accent }} />}
            </MenuItem>
          );
        })}
        {!shown.length && (
          <div style={{ padding: '8px 16px', color: colors.grey3, fontSize: 13 }}>No school found.</div>
        )}
      </Menu>
    </>
  );
};

export default SchoolSwitch;
